def reset():
    return 0

def on_button_a():
    global count
    count = add_one(count)
    show_number(count)

def on_button_b():
    global count
    count = reset()
    show_number(count)

count = 0
show_number(count)
while True:
    if button_a.was_pressed():
        on_button_a()
    if button_b.was_pressed():
