// 시작 방향에서 얼마나 돌았나: -180 ~ 180 (오른쪽 +, 왼쪽 -)
function turned (start: number, now: number) {
    d = (now - start) % 360
    if (d > 180) {
        d = d - 360
    }
    return d
}
