from microbit import *
import math

def show_number(n):
    # MakeCode 의 '수 출력' 과 같게: 한 자리 정수는 그대로, 아니면 흘려서 보이기
    if n == int(n) and 0 <= n <= 9:
        display.show(int(n))
    else:
        display.scroll(n)

def show_string(s):
    # MakeCode 의 '문자열 출력' 과 같게: 한 글자는 그대로, 아니면 흘려서 보이기
    if len(s) == 1:
        display.show(s)
    else:
        display.scroll(s)

# 준비된 함수: 흔들림 세기 (ch02 에서 만든 것)
def strength():
    global x, y, z
    x = accelerometer.get_x()
    y = accelerometer.get_y()
    z = accelerometer.get_z()
    return int(math.sqrt(x * x + y * y + z * z))

# 준비된 함수: 최근 4개 값의 평균 (들쭉날쭉한 선을 부드럽게)
def smooth(value):
    recent.append(value)
    if len(recent) > 4:
        recent.pop(0)
    return sum_list(recent) // len(recent)

# 준비된 함수: 목록의 값을 모두 더하기
def sum_list(values):
    global sum_total
    sum_total = 0
    for sum_item in values:
        sum_total += sum_item
    return sum_total

def on_button_a():
    global biggest, smallest, s
    display.show(Image.ARROW_S)
    biggest = 0
    smallest = 9999
    # 0.02초 x 250번 = 5초
    for i in range(250):
        s = smooth(strength())
        if s > biggest:
            biggest = s
        if s < smallest:
            smallest = s
        sleep(20)
    print("최고: " + str(biggest) + "  최저: " + str(smallest))
    show_number(biggest)
    show_string("A")

