from microbit import *
import music

def show_number(n):
    # MakeCode 의 '수 출력' 과 같게: 한 자리 정수는 그대로, 아니면 흘려서 보이기
    if n == int(n) and 0 <= n <= 9:
        display.show(int(n))
    else:
        display.scroll(n)

# 준비된 함수: 지금 박자 소리를 낼 때이면 True
def beat_due(bpm):
    global now, gap, next_beat
    now = running_time()
    if now < next_beat:
        return False
    gap = 60000 // bpm
    next_beat += gap
    # 너무 뒤처졌으면 지금부터 다시
    if next_beat < now:
        next_beat = now + gap
    return True

def on_button_a():
    global target
    if target > 60:
        target += -5
        show_number(target)

def on_button_b():
    global target
    if target < 200:
        target += 5
        show_number(target)

def on_forever():
    if beat_due(target):
        music.pitch(1760, 30, wait=False)
    sleep(20)

now = 0
gap = 0
next_beat = 0
# 목표 BPM
target = 120
while True:
    if button_a.was_pressed():
        on_button_a()
    if button_b.was_pressed():
        on_button_b()
    on_forever()
    sleep(20)

