function beat_due (bpm: number) {
    now = input.runningTime()
    if (now < next_beat) {
        return false
    }
    gap = Math.idiv(60000, bpm)
    next_beat += gap
    // 너무 뒤처졌으면 지금부터 다시
    if (next_beat < now) {
        next_beat = now + gap
    }
    return true
}
