// 준비된 함수: 키(cm)로 보폭(cm)을 어림하기 (대략값)
function stride_from_height (height: number, running: boolean) {
    if (running) {
        // 달리기: 키의 약 60%
        return Math.idiv(height * 60, 100)
    }
    // 걷기: 키의 약 41%
    return Math.idiv(height * 41, 100)
}
for (let h of [130, 150, 170]) {
    serial.writeLine("키 " + h + " cm → 걷기 " + stride_from_height(h, false) + " cm · 달리기 " + stride_from_height(h, true) + " cm")
}
