// 준비된 함수: heading 방향으로 stride 만큼 한 칸 밀기 -> 새 위치 (ch06)
function move (x: number, y: number, heading: number, stride: number): number[] {
    rad = heading * Math.PI / 180
    return [x + stride * Math.sin(rad), y + stride * Math.cos(rad)]
}
// 준비된 함수: 지도에서 글자 ch 가 있는 칸 (열, 줄)
function find (ch: string): number[] {
    for (let r = 0; r <= ROOM.length - 1; r++) {
