// 준비된 함수: 흔들림 세기 (ch02)
function strength () {
    x_strength = input.acceleration(Dimension.X)
    y_strength = input.acceleration(Dimension.Y)
    z = input.acceleration(Dimension.Z)
    return Math.trunc(Math.sqrt(x_strength * x_strength + y_strength * y_strength + z * z))
}
// 준비된 함수: 최근 4개 값의 평균 (ch03)
function smooth (value: number) {
    recent.push(value)
    if (recent.length > 4) {
        recent.shift()
    }
    return Math.idiv(sum_list(recent), recent.length)
}
// 준비된 함수: 걸음이면 True (ch03)
function is_step (value: number) {
    if (value > THRESHOLD) {
        above = true
        return false
    }
    if (above) {
        above = false
        now = input.runningTime()
        if (now - last_step >= MIN_GAP) {
            last_step = now
            return true
        }
    }
    return false
}
// 준비된 함수: heading 방향으로 stride 만큼 한 칸 밀기 -> 새 위치 (ch06)
function move (x: number, y: number, heading: number, stride2: number): number[] {
    rad = heading * Math.PI / 180
    return [x + stride2 * Math.sin(rad), y + stride2 * Math.cos(rad)]
}
// 준비된 함수: 아는 거리를 걸은 걸음 수로 보폭 다시 정하기
function calibrate_stride (real_cm: number, counted_steps: number) {
    return Math.round(real_cm / counted_steps)
}
// 준비된 함수: 도면 위쪽을 보고 여러 번 읽은 방위의 '원 평균'
function heading_offset (samples: number) {
    sx = 0
    sy = 0
    for (let i = 0; i <= samples - 1; i++) {
        rad = input.compassHeading() * Math.PI / 180
        sx += Math.sin(rad)
        sy += Math.cos(rad)
        basic.pause(50)
    }
    return Math.round(Math.atan2(sx, sy) * 180 / Math.PI) % 360
}
// 준비된 함수: 바뀐 각도가 limit 보다 작으면 직진으로 보고 이전 방향 유지
function keep_straight (new_h: number, last_h: number, limit: number) {
    diff = (new_h - last_h + 180) % 360 - 180
    if (Math.abs(diff) < limit) {
        return last_h
    }
    return new_h
}
// 준비된 함수: 지금 위치에서 가장 가까운 랜드마크 (이름, x, y)
function nearest_landmark (x: number, y: number): number[] {
    // [파이썬] best = None
    // [파이썬] for name in LANDMARKS:
    // [파이썬]     lx, ly = LANDMARKS[name]
    // [파이썬]     d = (lx - x) ** 2 + (ly - y) ** 2
    // [파이썬]     if best is None or d < best[0]:
    // [파이썬]         best = (d, name, lx, ly)
    return [best[1], best[2], best[3]]
}
// 준비된 함수: 목록의 값을 모두 더하기
function sum_list (values: number[]) {
    sum_total = 0
    for (let sum_item of values) {
        sum_total += sum_item
    }
    return sum_total
}
// 도면 위쪽을 보고 출발
